import datetime

from airflow.providers.standard.operators.empty import EmptyOperator
from airflow.sdk import DAG, result, task, task_group

with DAG(
    dag_id="loops_34",
    description="Airflow 3.4 task loop: refine an estimate until it converges",
    schedule=None,
    start_date=datetime.datetime(2026, 1, 1, tzinfo=datetime.timezone.utc),
    catchup=False,
) as dag:
    t_start = EmptyOperator(task_id="start")

    @result
    @task(task_id="report")
    def report():
        return "converged"

    t_report = report()

    @task_group(group_id="refine")
    def g_refine_body():

        @task(task_id="improve")
        def improve(*, loop=None):
            x = 1.0 if loop.index == 0 else loop.previous
            return (x + 2 / x) / 2

        t_improve = improve()

        @task(task_id="evaluate")
        def evaluate(x):
            return x

        t_evaluate = evaluate(x=t_improve)
        t_improve >> t_evaluate

    def accurate_enough(**context):
        loop = context["loop"]
        return abs(loop.result - 2**0.5) < 1e-06

    g_refine = g_refine_body.loop(max_iterations=8, until=accurate_enough)
    t_start >> g_refine
    g_refine >> t_report
